// api/og-image.js — serves the StitchDesk link-preview image (1200x630 PNG).
// The PNG is embedded as base64 here because the GitHub connector cannot push
// raw binary files (it UTF-8-expands binary bytes and corrupts them).
// Served at https://stitch-desk-sage.vercel.app/api/og-image
const B64 = "";
export default function handler(req, res) {
  const buf = Buffer.from(B64, "base64");
  res.setHeader("Content-Type", "image/png");
  res.setHeader("Cache-Control", "public, max-age=86400");
  res.setHeader("Content-Length", String(buf.length));
  res.status(200).send(buf);
}
